# ---------- 1) المحتوى ----------
def lesson(rel):
  return lambda root: os.path.join(root, 'content', 'm1', 'u3', rel)
def edit(root, rel, fn):   # والطفرة التي لا تغيّر شيئاً (نصٌّ تغيّر في المحتوى فصار replace لا يجد ما يبدّله) تُعلَن ولا تُعدّ (بوابة S1-U4، إصلاح E1: نجت «ستة مكعبات» لذلك)
  p = lesson(rel)(root); d = json.load(open(p, encoding='utf-8')); d0 = json.dumps(d, sort_keys=True); fn(d)
  json.dump(d, open(p, 'w', encoding='utf-8'), ensure_ascii=False, indent=1); return json.dumps(d, sort_keys=True) != d0
def set_(path, v):   # path: مفاتيح وفهارس
  def fn(d):
    x = d
    for k in path[:-1]: x = x[k]
    assert path[-1] in x if isinstance(x, dict) else path[-1] < len(x), path
    x[path[-1]] = v
  return fn
def test_item(d, i): return next(q for q in d['test']['items'] if q['id'] == i)['item']
def line_rep(k, a, b):   # جملة الدرس بصيغتها (نصٌّ أو [المتكلّم، النصّ])
  def fn(d):
    v = d['lines'][k]; t = v if isinstance(v, str) else v[1]; assert a in t, (k, a)
    d['lines'][k] = t.replace(a, b) if isinstance(v, str) else [v[0], t.replace(a, b)]
  return fn
def line_any(a, b):   # أول جملة في الدرس فيها النصّ
  def fn(d):
    for k, v in d['lines'].items():
      t = v if isinstance(v, str) else v[1] if isinstance(v, list) and len(v) == 2 and isinstance(v[1], str) else None
      if t and a in t: d['lines'][k] = t.replace(a, b) if isinstance(v, str) else [v[0], t.replace(a, b)]; return
    raise AssertionError(a)
  return fn
def deep_rep(a, b):   # أول نصٍّ فيه a في أي موضع من الملف (errors.json وgen.json بأقسامهما)
  def fn(d):
    def go(x):
      it = x.items() if isinstance(x, dict) else enumerate(x) if isinstance(x, list) else ()
      for k, v in list(it):
        if isinstance(v, str) and a in v: x[k] = v.replace(a, b, 1); return True
        if go(v): return True
      return False
    assert go(d), a
  return fn
