def lint(root):
  r = subprocess.run(['node', 'build/lint.mjs'], cwd=root, capture_output=True, text=True); return r.returncode, r.stdout + r.stderr

# وتُقسَم على جزأين حين يحدّ المشغّل زمن المهمة (MUT_PART=1: المحتوى والمولّد والكود ونصف طفرات المتصفح الأول، و2: نصفها الثاني؛ بوابة S1-U4 بعد E:
# تجاوزت الطفرات كلها ساعة ونصفاً فقطعها الحدّ الزمني بعد ستين طفرة متصفح بلا إخفاق، والخلاصة رأت التوقّف)
MUT_PART = os.environ.get('MUT_PART', '')
tmp = tempfile.mkdtemp(prefix='mut_')
try:
  if MUT_PART == '2' or os.environ.get('MUT_ONLY'): raise StopIteration   # MUT_ONLY: طفرة متصفح واحدة بالاسم، لإعادة فحص طفرةٍ عُدّلت
  root = os.path.join(tmp, 'engine')
  shutil.copytree(ROOT, root, ignore=shutil.ignore_patterns('dist', 'out', '.git', '__pycache__', 'node_modules'))
  rc, out = lint(root); check(rc == 0, 'الأصل: فحص المحتوى بلا مخالفة')
  for name, rel, fn, want in CONTENT:
    p = lesson(rel)(root); keep = open(p, encoding='utf-8').read()
    changed = edit(root, rel, fn); rc, out = lint(root); open(p, 'w', encoding='utf-8').write(keep)
    hit = [l.strip() for l in out.splitlines() if want in l]
    check(changed and rc == 1 and bool(hit), 'طفرة المحتوى «%s»: %s %s' % (name, 'أخفق الفحص بالرسالة المقصودة' if changed else 'لا تغيّر شيئاً في المحتوى', (hit or out.splitlines()[-3:])[:1]))
  # وطفرات في الكود يقرؤها فحص المحتوى: نوع بند بلا توأم (كان «twin: () => null» في ثمانية أنواع، الفحص المستقل B)
  for name, rel, old, new, want in CODE:
    p = os.path.join(root, rel); keep = open(p, encoding='utf-8').read()
    if keep.count(old) != 1: check(False, 'طفرة الكود «%s»: النصّ يظهر %d مرة' % (name, keep.count(old))); continue
    open(p, 'w', encoding='utf-8').write(keep.replace(old, new)); rc, out = lint(root); open(p, 'w', encoding='utf-8').write(keep)
    hit = [l.strip() for l in out.splitlines() if want in l]
    check(rc == 1 and bool(hit), 'طفرة الكود «%s»: أخفق الفحص بالرسالة المقصودة %s' % (name, (hit or out.splitlines()[-3:])[:1]))
  for name, rel, old, new in CODE_OK:
    p = os.path.join(root, rel); keep = open(p, encoding='utf-8').read()
    if keep.count(old) != 1: check(False, 'كود مشروع «%s»: النصّ يظهر %d مرة' % (name, keep.count(old))); continue
    open(p, 'w', encoding='utf-8').write(keep.replace(old, new)); rc, out = lint(root); open(p, 'w', encoding='utf-8').write(keep)
    check(rc == 0, 'كود مشروع «%s»: يمرّ به فحص المحتوى %s' % (name, [l.strip() for l in out.splitlines() if 'مخالفة' in l][:1]))
  # ومولّد المحتوى يتوقّف على المفتاح المكرّر في قاموس (بوابة S1-U4: وسم خطأ جديد باسم وسمٍ قائم محاه صامتاً، الدرس 139)
  for name, rel, old, new, want in GEN:
    p = os.path.join(root, rel); keep = open(p, encoding='utf-8').read()
    if keep.count(old) != 1: check(False, 'طفرة المولّد «%s»: النصّ يظهر %d مرة' % (name, keep.count(old))); continue
    open(p, 'w', encoding='utf-8').write(keep.replace(old, new)); r = subprocess.run(['python3', os.path.basename(p)], cwd=os.path.dirname(p), capture_output=True, text=True); open(p, 'w', encoding='utf-8').write(keep)
    out = r.stdout + r.stderr; hit = [l.strip() for l in out.splitlines() if want in l]
    check(r.returncode != 0 and bool(hit), 'طفرة المولّد «%s»: توقّف بالرسالة المقصودة %s' % (name, (hit or out.splitlines()[-2:])[:1]))
except StopIteration: pass
finally:
  shutil.rmtree(tmp, ignore_errors=True)

