def run(args, env, f):
  e = dict(os.environ, **env, FILE=f)
  try: r = subprocess.run(['python3'] + [a.replace('{F}', f) for a in args], cwd=ROOT, capture_output=True, text=True, env=e, timeout=1800)
  except subprocess.TimeoutExpired as x:   # فحصٌ لا ينتهي إخفاقٌ يُسجَّل لا توقّفٌ للطفرات كلها (بوابة S1-U4: توقّف التشغيل كله على أصلٍ لم ينتهِ)
    out = (x.stdout or b'') + (x.stderr or b''); out = out.decode('utf-8', 'replace') if isinstance(out, bytes) else out
    return 124, out + '\nTIMEOUT بعد 1800 ثانية'
  return r.returncode, r.stdout + r.stderr
src = open(DEV, encoding='utf-8').read(); tmpd = tempfile.mkdtemp(prefix='mutf_')
# وقبل أي تشغيل: نصّ كل طفرة في المتصفح يظهر مرة واحدة في نسخة الفحص (الدرس 177: الطفرة تشيخ حين يتغيّر ما تكسره، فكانت تظهر بعد ساعة من الطفرات)
# والطفرة بنصوص عدّة حين يحرس الخطأَ موضعان (الفحص المستقل H2: الفاصل الموقوف وانتظار الإيقاف قبل البطاقة التالية كلاهما): old وnew قائمتان متناظرتان
def PAIRS(old, new): return list(zip(old, new)) if isinstance(old, tuple) else [(old, new)]
def COUNTS(src, old, new): return [src.count(o) for o, _ in PAIRS(old, new)]
def APPLY(src, old, new):
  for o, n in PAIRS(old, new): src = src.replace(o, n)
  return src
for name, old, new, args, env, want in RUNTIME:
  if COUNTS(src, old, new) != [1] * len(PAIRS(old, new)): check(False, 'طفرة «%s»: النصّ يظهر %s مرة في نسخة الفحص (يجب مرة واحدة)' % (name, COUNTS(src, old, new)))
if os.environ.get('CONTENT_ONLY'): print('FAILS:', len(FAILS)); shutil.rmtree(tmpd, ignore_errors=True); sys.exit(1 if FAILS else 0)
K = (len(RUNTIME) + 1) // 2; RT = RUNTIME[:K] if MUT_PART == '1' else RUNTIME[K:] if MUT_PART == '2' else RUNTIME
if os.environ.get('MUT_ONLY'): RT = [x for x in RUNTIME if any(x[0].startswith(q) for q in os.environ['MUT_ONLY'].split(','))]   # اسمٌ أو بدايات أسماء مفصولة بفواصل
try:
  for args, env in dict.fromkeys((tuple(x[3]), tuple(sorted(x[4].items()))) for x in RT):   # كل فحص مرة على الأصل
    rc, out = run(list(args), dict(env), DEV); check(rc == 0, 'الأصل: %s %s ينجح %s' % (args[0], dict(env), ([l.strip()[:400] for l in out.splitlines() if l.startswith('FAIL ') or 'Traceback' in l or 'Error' in l][:6] if rc else []) + out.strip().splitlines()[-1:]))   # وسطور الإخفاق نفسها (كان السطر الأخير وحده «FAILS: 1»، فلم يُعرف ما أخفق)
  for name, old, new, args, env, want in RT:
    f = os.path.join(tmpd, 'mut.dev.html')
    if COUNTS(src, old, new) != [1] * len(PAIRS(old, new)): continue   # سُجّل في الفحص المسبق
    open(f, 'w', encoding='utf-8').write(APPLY(src, old, new)); rc, out = run(args, env, f)
    hit = [l.strip() for l in out.splitlines() if want in l]
    check(rc == 1 and bool(hit), 'طفرة «%s»: أخفق %s بالرسالة المقصودة %s' % (name, args[0], (hit or out.strip().splitlines()[-2:])[:1]))
finally:
  shutil.rmtree(tmpd, ignore_errors=True)
print('FAILS:', len(FAILS)); sys.exit(1 if FAILS else 0)
